import * as React from "react";
import clsx from "clsx";
import CircleIcon, { CircleIconStatus } from "../CircleIcon/CircleIcon";
import TimelineInfoContent from "../TimelineInfoContent/TimelineInfoContent";
import TimelineInfoDescription from "../TimelineInfoDescription/TimelineInfoDescription";
import "./TimelineInfo.scss";

export interface TimelineInfoProps {
  /**
   * Identifying value for the timeline info.
   */
  id?: string;
  /**
   * Title for timeline info
   */
  title: React.ReactNode;
  /**
   * Subtitle for timeline info
   */
  subtitle: React.ReactNode;
  /**
   * Custom icon component (overrides default CircleIcon)
   */
  icon?: React.ReactNode;
  /**
   * Semantic color indicating status type/severity
   */
  iconStatus?: CircleIconStatus;
  /**
   * Content to display for timeline info
   */
  content?: React.ReactNode;
  /**
   * Toggle to show vertical line on the left
   */
  showLine?: boolean;
}

const TimelineInfo = ({
  title,
  subtitle,
  icon,
  iconStatus,
  content,
  showLine,
}: TimelineInfoProps) => {
  return (
    <div className="timeline-info-container">
      <div className="timeline-info">
        <div className="timeline-info-icon-container">
          {icon ?? <CircleIcon status={iconStatus} />}
          {showLine && <div className="timeline-info-icon-line" />}
        </div>
        <TimelineInfoDescription title={title} subtitle={subtitle} />
      </div>

      {content && (
        <>
          <div
            className={clsx("timeline-info-gap", {
              "hide-info-line": !showLine,
            })}
          />
          <TimelineInfoContent content={content} showLine={showLine} />
        </>
      )}
    </div>
  );
};

export default TimelineInfo;
